const e={back:"Zurück",continue:"Weiter",step_of:"{current} von {total}",window:{title:"{name} einrichten",progress:"Fortschritt der Einrichtung",language:"Sprache"},name:{pill:"Name",title:"Hey! Wie möchtest du mich nennen?",lede:"Such dir einen Namen aus. Er ist auch mein Weckwort: Sag ihn laut, und ich höre zu. Du kannst ihn jederzeit in den Einstellungen ändern.",label:"Name des Assistenten",placeholder:"Namen eingeben…"},connect:{pill:"Verbinden",title:"Verbinde deine KI",lede:"Melde dich mit einem Abo an, das du schon bezahlst, oder füge einen API-Schlüssel ein. Eins davon reicht, damit {name} denken und sprechen kann.",sign_in:"Anmelden",api_key:"API-Schlüssel",ready:"Bereit",checking:"Wird geprüft…",waiting:"Warte…",signed_in:"Angemeldet",signed_in_as:"Angemeldet als {account}",key_saved:"API-Schlüssel gespeichert",plans_or_key:"{plans} oder ein API-Schlüssel",key_only:"API-Schlüssel",more:"Weitere Anbieter",finish_in_browser:"Schließ die Anmeldung in deinem Browser ab.",install_first:"Installiere es zuerst: Führe das in einem Terminal aus und prüfe dann erneut.",check_again:"Erneut prüfen",copy:"Befehl kopieren",key_connecting:"Alles wird eingeschaltet…",key_connected:"Verbunden: {provider}.",key_partial:"Einige Teile wurden nicht umgestellt ({parts}). Du kannst das später auf der Seite API-Schlüssel beheben.",live_ready:"Live-Sprache ist an: Sprich, und {name} antwortet sofort.",live_missing:"Der Chat funktioniert. Live-Sprache braucht einen OpenAI- oder Gemini-Schlüssel; bis dahin spricht {name} auf die klassische Art, etwas langsamer.",key_security:"Abos kosten einen festen Monatspreis. Schlüssel landen im Schlüsselbund deines Systems und gehen nur an den Anbieter, den du gewählt hast.",nothing_yet:"Noch nichts verbunden. Ohne Abo oder Schlüssel bleiben Chat und Sprache aus. Du kannst später auf der Seite API-Schlüssel etwas verbinden.",later:"Erst mal überspringen"},voice:{pill:"Stimme",title:"So sprichst du mit {name}",lede:"Schreib im Chat oder sprich einfach: Sag dein Weckwort oder drück dein Anruf-Tastenkürzel.",wake_title:"Weckwort: {phrase}",call_title:"Anruf-Tastenkürzel",call_detail:"Drück es irgendwo, um loszusprechen. Klick auf die Tasten, um dein eigenes festzulegen.",call_recording:"Halte die gewünschten Tasten gedrückt und lass dann los. Esc bricht ab.",call_none:"Noch kein Tastenkürzel. Klick auf das Feld und drück die gewünschten Tasten.",call_press:"Klicken, dann Tasten drücken",call_change:"Anruf-Tastenkürzel ändern",call_saved:"Gespeichert. Drück es irgendwo, um loszusprechen.",call_refused:"Diese Kombination geht nicht. Probier eine andere.",no_word:"Noch kein Weckwort",wake_on:"Hört immer auf dein Weckwort. Es wird direkt hier auf diesem Computer erkannt.",wake_off:"Aus: Drück dein Anruf-Tastenkürzel, um zu sprechen. Schalte es ein, damit dein Weckwort immer gehört wird.",wake_switch:"Immer auf das Weckwort hören",after_restart:"Das wird mit dem Neustart am Ende eingeschaltet.",login_title:"Beim Anmelden starten",login_detail:"Öffnet {name}, wenn dein Computer startet, damit es dich gleich hören kann.",preview_note:"Das ist eine Wiederholung, es wird nichts neu gestartet.",restart_note:"Als Nächstes zeigt dir ein kurzer Rundgang die App. Am Ende startet die App einmal neu (etwa zehn Sekunden), um alles einzuschalten.",start:"Zeig mir alles"},tour:{title:"Ein Rundgang durch {name}",lede:"Dein Haustier führt dich durch die App und erklärt jeden Bereich.",next:"Weiter",finish:"Los geht's",skip:"Überspringen",labels:{chat:"Chat",voice:"Sprach-Chat",agents:"Agents",ide:"Agentic IDE",plugins:"Plugins",wake:"Weckwort",permissions:"Mac-Berechtigungen",done:"Fertig"},stops:{chat:"Hi, ich bin {pet}! Ich zeig dir alles. Das ist dein Chat mit {name}. Schreib hier einfach rein: eine Frage, eine Aufgabe, eine Datei zum Anschauen. Du wählst nie selbst ein Werkzeug oder Modell; {name} entscheidet, was gebraucht wird.",voice:"Lieber reden? Das ist der Sprach-Chat. Klick auf die Leiste, sag dein Weckwort oder drück dein Anruf-Tastenkürzel und sprich einfach los. Die Welle zeigt, wer gerade spricht.",agents:"Große Aufgaben wie Recherche, ein Bericht oder eine Website gehen an deine Agents. Sie sind das Team von {name}, jeder mit eigener Rolle und eigenem Modell. Unter Agents siehst du ihnen bei der Arbeit zu, chattest mit einem oder erstellst deinen eigenen.",ide:"Die Agentic IDE lässt Coding-Agents wie Claude Code und Codex in echten Terminals an deinen eigenen Projekten arbeiten. Schreib ihnen direkt, oder lass {name} sie per Stimme steuern.",plugins:"Plugins verbinden {name} mit den Apps, die du nutzt: Mail, Kalender, Notizen, Smart Home und mehr. Jedes wird zu einem neuen Werkzeug, und alles, was etwas sendet oder ändert, fragt dich vorher.",wake:"Dein Weckwort findest du hier in den Einstellungen. Sag „Hey {name}“, und {name} hört zu. Ändere das Wort, wähle seine Sprache oder teste es jederzeit.",permissions:"Auf einem Mac braucht {name} deine Erlaubnis für Mikrofon, Bildschirm und die Steuerung von Apps. Erlaube hier, was du möchtest; jede Zeile aktualisiert sich von selbst.",done:"Das war der Rundgang! Sprich mit {name}, wann immer du willst, und wenn du mal nicht weiterweißt, frag einfach. Unter Einstellungen → App startest du diese Einführung erneut."}}},n={replay_title:"Einführung wiederholen",replay_body:"Öffnet das Einrichtungsfenster erneut (Name, KI-Verbindungen, Stimme) und danach den Rundgang durch die App. Es wird nichts neu gestartet.",replay:"Wiederholen"},i={first_run:e,app_tour:n};export{n as app_tour,i as default,e as first_run};
